public class BlockItemShelf extends BlockCyclic {

  public BlockItemShelf(Properties properties) {
    super(properties.strength(0.8F).noOcclusion());
  }

  @Override
  public boolean hasAnalogOutputSignal(BlockState bs) {
    return true;
  }

  @Override
  public int getAnalogOutputSignal(BlockState st, Level level, BlockPos pos) {
    return AbstractContainerMenu.getRedstoneSignalFromBlockEntity(level.getBlockEntity(pos));
  }

  @Override
  protected void createBlockStateDefinition(StateDefinition.Builder<Block, BlockState> builder) {
    builder.add(BlockStateProperties.HORIZONTAL_FACING);
  }

  @Override
  public BlockEntity newBlockEntity(BlockPos pos, BlockState state) {
    return new TileItemShelf(pos, state);
  }

  @Override
  public void onRemove(BlockState state, Level worldIn, BlockPos pos, BlockState newState, boolean isMoving) {

    if (!state.is(newState.getBlock())) {
      worldIn.removeBlockEntity(pos);
    }
  }

  @Override
  public InteractionResult useWithoutItem(BlockState state, Level world, BlockPos pos, Player player, BlockHitResult hit) {
    ItemStack heldItem = player.getMainHandItem();
    TileItemShelf shelf = getTileEntity(world, pos);
    if (heldItem.is(DataTags.WRENCH)) {
      //wrench tag
      shelf.toggleShowText();
      player.swing(InteractionHand.MAIN_HAND);
      return InteractionResult.PASS;
    }
    Direction face = hit.getDirection();
    Vec3 hitVec = hit.getLocation();
    int slot = BlockEnderShelf.getSlotFromHitVec(pos, face, hitVec);
    if (hit.getDirection() == state.getValue(BlockStateProperties.HORIZONTAL_FACING)) {
      //
      // single shelf
      ItemStack shelfStack = shelf.inventory.getStackInSlot(slot);
      //first , check if deposit spot is empty
      if (shelfStack.isEmpty() || heldItem.getItem() == shelfStack.getItem()) {
        //try to insert  
        boolean oldEmpty = shelfStack.isEmpty();
        ItemStack remaining = shelf.inventory.insertItem(slot, heldItem, false);
        shelf.updateComparatorOutputLevel();
        if (remaining.isEmpty() || remaining.getCount() != shelfStack.getCount()) {
          player.setItemInHand(InteractionHand.MAIN_HAND, remaining);
          player.swing(InteractionHand.MAIN_HAND);
          SoundUtil.playSound(player, SoundRegistry.CRACKLE.get(), oldEmpty ? 0.3F : 0.1F, 0.3F);

          return InteractionResult.CONSUME;
        }
      }
      if (heldItem.isEmpty()) {
        //withdraw direct to players empty hand
        int q = player.isCrouching() ? 1 : 64;
        ItemStack retrieved = shelf.inventory.extractItem(slot, q, false);
        player.setItemInHand(InteractionHand.MAIN_HAND, retrieved);
        player.swing(InteractionHand.MAIN_HAND);
        shelf.updateComparatorOutputLevel();
      }
      if (!shelfStack.isEmpty() && !heldItem.isEmpty()) {
        //
        ItemStack forShelf = heldItem.copy();
        //        ItemStack forPlayer = shelfStack.copy();
        //extract all from shelf
        ItemStack forPlayer = shelf.inventory.extractItem(slot, 64, false);
        player.setItemInHand(InteractionHand.MAIN_HAND, forPlayer);
        player.swing(InteractionHand.MAIN_HAND);
        shelf.inventory.insertItem(slot, forShelf, false);
        shelf.updateComparatorOutputLevel();
      }
      return InteractionResult.SUCCESS;
    }
    return InteractionResult.PASS;
  }

  public TileItemShelf getTileEntity(Level world, BlockPos pos) {
    return (TileItemShelf) world.getBlockEntity(pos);
  }

  @Override
  public List<ItemStack> getDrops(BlockState state, LootParams.Builder builder) {
    // because harvestBlock manually forces a drop, we must do this to dodge that0
    return new ArrayList<>();
  }

  @Override
  public void setPlacedBy(Level world, BlockPos pos, BlockState state, LivingEntity entity, ItemStack stack) {
    if (entity != null) {
      //facing state if needed
      world.setBlock(pos, state.setValue(BlockStateProperties.HORIZONTAL_FACING, BlockstatesUtil.getFacingFromEntityHorizontal(pos, entity)), 2);
    }
    BlockEntity tileentity = world.getBlockEntity(pos);
    if (!(tileentity instanceof TileItemShelf shelf)) {
      return;
    }
    //pull inventory from the item's capability (which loads from CUSTOM_DATA) into the tile
    IItemHandler stackInv = CapabilityUtil.item(stack);
    if (stackInv != null) {
      int slots = Math.min(stackInv.getSlots(), shelf.inventory.getSlots());
      for (int i = 0; i < slots; i++) {
        shelf.inventory.setStackInSlot(i, stackInv.getStackInSlot(i).copy());
      }
    }
  }

  @Override
  public void playerDestroy(Level world, Player player, BlockPos pos, BlockState state, BlockEntity tileentity, ItemStack stackToolUsed) {
    super.playerDestroy(world, player, pos, state, tileentity, stackToolUsed);
    ItemStack newStack = new ItemStack(this);
    if (tileentity instanceof TileItemShelf shelf) {
      //write the tile's inventory into the dropped item's capability (which persists into CUSTOM_DATA)
      IItemHandler stackInv = CapabilityUtil.item(newStack);
      if (stackInv instanceof ItemStackHandler sh) {
        int slots = Math.min(sh.getSlots(), shelf.inventory.getSlots());
        for (int i = 0; i < slots; i++) {
          sh.setStackInSlot(i, shelf.inventory.getStackInSlot(i).copy());
        }
      }
      CompoundTag tileData = shelf.inventory.serializeNBT(world.registryAccess());
      // newStack.setTag(tileData); // disabled: use DataComponents in 1.21.1
    }
    ItemStackUtil.dropItemStackMotionless(world, pos, newStack);
  }
}

package com.lothrazar.cyclic.block.enderitemshelf;

import com.lothrazar.cyclic.net.PacketTileInventoryToClient;
import com.lothrazar.cyclic.net.PacketTileInventoryToClient.SyncPacketType;
import com.lothrazar.cyclic.registry.PacketRegistry;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.neoforged.neoforge.items.ItemStackHandler;

public class ClientAutoSyncItemHandler extends ItemStackHandler {

  private BlockEntity shelf;

  public ClientAutoSyncItemHandler(BlockEntity shelf, int rows) {
    super(rows);
    this.shelf = shelf;
  }

  public ItemStack emptySlot(int slot) {
    ItemStack returnStack = this.getStackInSlot(slot);
    this.stacks.set(slot, ItemStack.EMPTY);
    return returnStack;
  }

  @Override
  public ItemStack extractItem(int slot, int amount, boolean simulate) {
    ItemStack extracted = super.extractItem(slot, amount, simulate);
    if (!simulate) {
      PacketRegistry.sendToAllClients(shelf.getLevel(), new PacketTileInventoryToClient(shelf.getBlockPos(), slot, getStackInSlot(slot), SyncPacketType.SET));
    }
    return extracted;
  }

  @Override
  public int getStackLimit(int slot, ItemStack stack) {
    return Math.min(getSlotLimit(slot), stack.getMaxStackSize());
  }

  @Override
  public ItemStack insertItem(int slot, ItemStack stack, boolean simulate) {
    if (!this.isItemValid(slot, stack)) {
      return stack; // not valid
    }
    ItemStack remaining = super.insertItem(slot, stack, simulate);
    if (!simulate) {
      PacketRegistry.sendToAllClients(shelf.getLevel(), new PacketTileInventoryToClient(shelf.getBlockPos(), slot, getStackInSlot(slot), SyncPacketType.SET));
    }
    return remaining;
  }
}

package com.lothrazar.cyclic.capabilities.item;

import com.lothrazar.cyclic.util.RegistryHolder;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.component.CustomData;
import net.neoforged.neoforge.items.ItemStackHandler;

/**
 * Item-level inventory capability backed by the host stack's CUSTOM_DATA component.
 * Reads/writes the full ItemStackHandler NBT under the "inventory" key so contents
 * persist across place/break cycles.
 */
public class ItemInventoryCap extends ItemStackHandler {

  private static final String KEY = "inventory";
  private final ItemStack host;

  public ItemInventoryCap(ItemStack host, int slots) {
    super(slots);
    this.host = host;
    var registries = RegistryHolder.get();
    if (registries != null) {
      CompoundTag data = host.getOrDefault(DataComponents.CUSTOM_DATA, CustomData.EMPTY).copyTag();
      if (data.contains(KEY)) {
        deserializeNBT(registries, data.getCompound(KEY));
      }
    }
  }

  @Override
  protected void onContentsChanged(int slot) {
    var registries = RegistryHolder.get();
    if (registries == null) {
      return;
    }
    CompoundTag data = host.getOrDefault(DataComponents.CUSTOM_DATA, CustomData.EMPTY).copyTag();
    data.put(KEY, serializeNBT(registries));
    host.set(DataComponents.CUSTOM_DATA, CustomData.of(data));
  }
}

package com.lothrazar.cyclic.net;

import net.minecraft.core.BlockPos;
import net.minecraft.world.item.ItemStack;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.ResourceLocation;
import net.neoforged.neoforge.network.handling.IPayloadContext;
import com.lothrazar.cyclic.ModCyclic;

public class PacketTileInventoryToClient implements CustomPacketPayload {

  public static final CustomPacketPayload.Type<PacketTileInventoryToClient> TYPE = new CustomPacketPayload.Type<>(ResourceLocation.fromNamespaceAndPath(ModCyclic.MODID, "packet_tile_inventory_to_client"));

  public static final StreamCodec<RegistryFriendlyByteBuf, PacketTileInventoryToClient> STREAM_CODEC = StreamCodec.of(PacketTileInventoryToClient::encode, PacketTileInventoryToClient::decode);


  @Override
  public CustomPacketPayload.Type<? extends CustomPacketPayload> type() {
    return TYPE;
  }


  BlockPos blockPos;
  int slot;
  ItemStack itemStack;
  SyncPacketType type;

  public static enum SyncPacketType {
    CHANGE, SET
  }

  public PacketTileInventoryToClient(BlockPos blockPos, int slot, ItemStack itemStack, SyncPacketType type) {
    this.blockPos = blockPos;
    this.slot = slot;
    this.itemStack = itemStack;
    this.type = type;
  }

  public PacketTileInventoryToClient() {}

  public static void handle(PacketTileInventoryToClient message, IPayloadContext ctx) {
    ctx.enqueueWork(() -> ClientNetHandlers.handleTileInventory(message));
  }

  public static PacketTileInventoryToClient decode(RegistryFriendlyByteBuf buf) {
    PacketTileInventoryToClient p = new PacketTileInventoryToClient();
    p.blockPos = buf.readBlockPos();
    p.slot = buf.readInt();
    p.itemStack = ItemStack.OPTIONAL_STREAM_CODEC.decode(buf);
    p.type = buf.readEnum(SyncPacketType.class);
    return p;
  }

  public static void encode(RegistryFriendlyByteBuf buf, PacketTileInventoryToClient msg) {
    buf.writeBlockPos(msg.blockPos);
    buf.writeInt(msg.slot);
    ItemStack.OPTIONAL_STREAM_CODEC.encode(buf, msg.itemStack);
    buf.writeEnum(msg.type);
  }
}

package com.lothrazar.cyclic.net;

import com.lothrazar.cyclic.block.enderitemshelf.ClientAutoSyncItemHandler;
import com.lothrazar.cyclic.block.endershelf.EnderShelfItemHandler;
import com.lothrazar.cyclic.util.CapabilityUtil;
import net.minecraft.client.Minecraft;
import net.minecraft.world.item.ItemStack;
public final class ClientNetHandlers {

  private ClientNetHandlers() {}

  public static void handleTileInventory(PacketTileInventoryToClient message) {
    if (Minecraft.getInstance().level == null) {
      return;
    }
    var item = CapabilityUtil.item(Minecraft.getInstance().level, message.blockPos);
    if (item != null) {
      if (message.type == PacketTileInventoryToClient.SyncPacketType.SET) {
        if (item instanceof EnderShelfItemHandler es) {
          ItemStack extracted = es.emptySlot(message.slot);
        }
        else if (item instanceof ClientAutoSyncItemHandler cas) {
          ItemStack extracted = cas.emptySlot(message.slot);
        }
        else {
          item.extractItem(message.slot, 64, false);
        }
      }
      item.insertItem(message.slot, message.itemStack, false);
    }
  }

  public static void handlePlayerSync(PacketPlayerSyncToClient message) {
    Minecraft.getInstance().player.getAbilities().mayfly = message.mayfly;
    if (!message.mayfly) {
      Minecraft.getInstance().player.getAbilities().flying = false;
    }
  }

}

package com.lothrazar.cyclic.util;

import java.util.function.Supplier;
import net.minecraft.core.HolderLookup;
import net.neoforged.neoforge.server.ServerLifecycleHooks;

/**
 *
 * Client setup populates {@link #CLIENT_LOOKUP} via FMLClientSetupEvent so this class
 * never directly references any client-only types, keeping it safe to load on dedicated server.
 */
public class RegistryHolder {

  // Set by the client during FMLClientSetupEvent. Returns null on server.
  public static volatile Supplier<HolderLookup.Provider> CLIENT_LOOKUP = () -> null;


  /**
   *
   * Provides a HolderLookup.Provider that works on both sides:
   *   - Server: ServerLifecycleHooks.getCurrentServer().registryAccess()
   *   - Client (including dedicated-server clients): supplied by a client-side init hook
   */
  public static HolderLookup.Provider get() {
    var server = ServerLifecycleHooks.getCurrentServer();
    if (server != null) {
      return server.registryAccess();
    }
    return CLIENT_LOOKUP.get();
  }

}

